gafP(){return"\u0695\u06cc\u0632\u06ce\u06a9 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06cc \u0628\u06c6 \u062f\u06cc\u0627\u0631\u06cc \u0646\u06d5\u06a9\u0631\u0627\u0648\u06d5. \u0646\u0627\u0648\u06cc \u067e\u0634\u06a9\u0646\u06cc\u0646\u06d5\u06a9\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5\u060c \u06cc\u0627\u0646 \u0695\u06cc\u0632\u06d5\u06a9\u06d5 \u0644\u0627\u0628\u0628\u06d5."},
gafJ(){return"\u06cc\u06d5\u06a9\u06ce\u06a9 \u0644\u06d5 \u0628\u06d5\u0647\u0627\u06a9\u0627\u0646 \u0644\u06d5 \u062f\u06d5\u0631\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06a9\u06d5 \u0628\u06c6 \u0626\u06d5\u0645 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06d5 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u2014 \u0628\u06d5 \u0626\u06d5\u06af\u06d5\u0631\u06cc \u0632\u06c6\u0631 \u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u0647\u06d5\u06b5\u06d5\u06cc\u06d5. \u0644\u06d5\u06af\u06d5\u06b5 \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u06d5 \u0628\u06d5\u0631\u0627\u0648\u0631\u062f\u06cc \u0628\u06a9\u06d5."},
gafL(){return"\xab\u0626\u0627\u0633\u0627\u06cc\u06cc\xbb \u0648 \xab\u0646\u0627\u0626\u0627\u0633\u0627\u06cc\u06cc\xbb \u0628\u0695\u06cc\u0627\u0631\u0646\u060c \u0646\u06d5\u06a9 \u0626\u06d5\u0646\u062c\u0627\u0645\u06ce\u06a9\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648. \u0626\u06d5\u0646\u062c\u0627\u0645\u06d5\u06a9\u06d5 \u0628\u0646\u0648\u0648\u0633\u06d5 \u0647\u06d5\u0631\u0648\u06d5\u06a9 \u0644\u06d5 \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u06d5\u062f\u0627 \u0686\u0627\u067e\u06a9\u0631\u0627\u0648\u06d5."},
gafI(){return"\u0626\u06d5\u0648 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06d5\u06cc \u0626\u06d5\u0645 \u0628\u06d5\u0647\u0627\u06cc\u0627\u0646\u06d5\u06cc \u0644\u06ce\u0648\u06d5 \u0647\u0627\u062a\u0648\u0648\u0646 \u0644\u0627\u0628\u0631\u0627\u0648\u06d5\u060c \u0628\u06c6\u06cc\u06d5 \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u062e\u0631\u06ce\u0646\u06d5 \u0646\u0627\u0648 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a."},
gafO(){return"\u0626\u06d5\u0645 \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5\u06cc\u06d5 \u067e\u06ce\u0634\u062a\u0631 \u0632\u06cc\u0627\u062f\u06a9\u0631\u0627\u0648\u06d5 \u06cc\u0627\u0646 \u0686\u06cc\u062a\u0631 \u0628\u06d5\u0631\u062f\u06d5\u0633\u062a \u0646\u06cc\u06cc\u06d5. \u0634\u0627\u0634\u06d5\u06a9\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5."},
gagx(){return"\u0628\u06d5\u0647\u0627\u06a9\u0627\u0646 \u062e\u0631\u0627\u0646\u06d5 \u0646\u0627\u0648 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a"},
gagw(){return"\u0628\u06d5\u0647\u0627\u06a9\u06d5 \u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0634\u0627\u0631\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5 \u2014 \u0646\u06d5\u0633\u0695\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5\u060c \u0648 \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06af\u06d5\u0695\u06ce\u0646\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5"},
gagv(){return"\u0695\u0627\u067e\u06c6\u0631\u062a\u06d5\u06a9\u06d5 \u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0634\u0627\u0631\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5 \u2014 \u0646\u06d5\u0633\u0695\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5\u060c \u0648 \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06af\u06d5\u0695\u06ce\u0646\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5"},
agu(a){return"\u06a9\u06c6\u062f\u06cc \u0647\u06d5\u06b5\u06d5: "+a},
gTP(){return"\u0628\u06d5 \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f \u062f\u06d5\u0631\u0647\u06ce\u0646\u0631\u0627\u0648\u06d5 \u2014 \u0628\u06d5\u0645 \u0632\u0648\u0648\u0627\u0646\u06d5 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0627\u0648 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06cc \u062f\u06d5\u06a9\u0627\u062a\u06d5\u0648\u06d5"},
ga63(){return"\u0686\u06c6\u0646 \u0695\u0627\u067e\u06c6\u0631\u062a\u06d5\u06a9\u0627\u0646\u062a \u062f\u06d5\u062e\u0648\u06ce\u0646\u06cc\u0646\u06d5\u0648\u06d5"},
ga60(){return"\u0661 \xb7 \u0626\u06d5\u06cc\u062c\u06d5\u0646\u062a\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u0645\u0627\u0646 \u0628\u06d5\u0647\u0627\u06a9\u0627\u0646\u06cc \u0646\u0627\u0648 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u06d5\u062a \u062f\u06d5\u062e\u0648\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5."},
ga61(){return"\u0662 \xb7 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0627\u0648 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06cc\u0627\u0646 \u0628\u06c6 \u062f\u06d5\u06a9\u0627\u062a."},
ga62(){return"\u0663 \xb7 \u0647\u06ce\u06b5\u06a9\u0627\u0631\u06cc \u0648 \u0628\u06d5\u062f\u0648\u0627\u062f\u0627\u0686\u0648\u0648\u0646\u062a \u0644\u06d5 \u0628\u06d5\u0647\u0627\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u0628\u06ce\u062a."},
ga6_(){return"\u0648\u06ce\u0646\u06d5\u06cc \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u06d5 \u0628\u06c6 \u062e\u0632\u0645\u06d5\u062a\u06af\u0648\u0632\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u06cc \u062f\u06d5\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0646\u06ce\u0631\u062f\u0631\u06ce\u062a \u0628\u06c6 \u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc. \u0646\u0627\u0648\u062a \u0648 \u0698\u0645\u0627\u0631\u06d5 \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc\u06cc\u06d5\u06a9\u06d5\u062a \u0648 \u0647\u06cc\u0686 \u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u0646\u0627\u0633\u06ce\u0646\u06d5\u0631\u062a \u0644\u06d5\u06af\u06d5\u06b5\u06cc\u062f\u0627 \u0646\u0627\u0646\u06ce\u0631\u062f\u0631\u06ce\u062a\u060c \u0648 \u0646\u0627\u0648\u06d5\u0695\u06c6\u06a9\u06cc \u0695\u0627\u067e\u06c6\u0631\u062a\u06d5\u06a9\u06d5 \u0644\u06d5 \u0647\u06cc\u0686 \u062a\u06c6\u0645\u0627\u0631\u06ce\u06a9\u06cc \u06a9\u0627\u0631\u06a9\u0631\u062f\u0646\u062f\u0627 \u0646\u0627\u0646\u0648\u0648\u0633\u0631\u06ce\u062a. \u0647\u06cc\u0686 \u0628\u06d5\u0647\u0627\u06cc\u06d5\u06a9 \u0646\u0627\u062e\u0631\u06ce\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a\u06d5\u0648\u06d5 \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u062e\u06c6\u062a \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06cc \u0628\u06a9\u06d5\u06cc\u062a\u06d5\u0648\u06d5."},
