gag2(){return"\u0626\u06d5\u0631\u06ce\u0646\u06cc"},
gag1(){return"\u0646\u06d5\u0631\u06ce\u0646\u06cc"},
gagi(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648\u06cc \u0633\u06d5\u0631 \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u06d5 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5"},
gajB(){return"\u0626\u06d5\u0648 \u0628\u06d5\u0647\u0627\u06cc\u0627\u0646\u06d5\u06cc \u0644\u06d5 \u0695\u0627\u067e\u06c6\u0631\u062a\u06ce\u06a9\u06cc \u0628\u0627\u0631\u06a9\u0631\u0627\u0648\u06d5\u0648\u06d5 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06cc\u0627\u0646 \u062f\u06d5\u06a9\u06d5\u06cc\u062a\u06d5\u0648\u06d5 \u0644\u06ce\u0631\u06d5 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u0646"},
gTe(){return"\u0646\u06d5\u0645\u0627\u0646\u062a\u0648\u0627\u0646\u06cc \u0626\u06d5\u0645 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06d5 \u067e\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5\u06cc\u0646"},
gaoa(){return"\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5\u0631\u06d5\u0648\u06d5"},
aeb(a,b){return"\u0644\u0627\u067e\u06d5\u0695\u06d5\u06cc "+a+" \u0644\u06d5 "+b},
gafW(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u06cc\u0646 \u0634\u0648\u06ce\u0646\u06cc \u0626\u06d5\u0645 \u0628\u06d5\u0647\u0627\u06cc\u06d5 \u0644\u06d5 \u0644\u0627\u067e\u06d5\u0695\u06d5\u06a9\u06d5\u062f\u0627 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u06d5\u06cc\u0646 \u2014 \u062e\u06c6\u062a \u0644\u06d5\u0633\u06d5\u0631 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u06d5 \u0628\u06cc\u067e\u0634\u06a9\u0646\u06d5"},
TO(a){return""+a+" \u0695\u0627\u067e\u06c6\u0631\u062a \u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5\u062a\u0646"},
gTN(){return"\u0626\u06ce\u0633\u062a\u0627 \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5\u06cc \u0628\u06c6 \u0628\u06a9\u06d5"},
gaec(){return"\u0644\u0627\u067e\u06d5\u0695\u06d5\u06cc \u067e\u06ce\u0634\u0648\u0648"},
