gam8(){return"\u067e\u06d5\u0695\u06d5\u06a9\u06d5 \u0686\u0627\u067e \u0628\u06a9\u06d5"},
gami(){return"\u0628\u0646\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u067e\u06cc \u0646\u06d5\u062e\u06c6\u0634"},
galV(){return"\u0695\u0627\u062f\u06d5\u0633\u062a \u06a9\u0631\u0627"},
