gap1(){return"\u0647\u06cc\u0686 \u0646\u0627\u0633\u06ce\u0646\u06d5\u0631\u06ce\u06a9\u062a \u067e\u06ce\u0646\u0627\u06af\u0627\u062a: \u0646\u06d5 \u0646\u0627\u0648\u060c \u0646\u06d5 \u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc\u060c \u0646\u06d5 \u062a\u06d5\u0645\u06d5\u0646\u060c \u0646\u06d5 \u0695\u06d5\u06af\u06d5\u0632\u060c \u0648 \u0646\u06d5 \u06cc\u06d5\u06a9 \u062f\u06ce\u0695\u06cc \u062a\u0631\u06cc \u062a\u06c6\u0645\u0627\u0631\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5."},
gaoG(){return"\u0628\u06d5\u06b5\u0627\u0645 \u067e\u06d5\u0695\u06d5\u06a9\u06d5 \u062e\u06c6\u06cc \u0644\u06d5\u0648\u0627\u0646\u06d5\u06cc\u06d5 \u0646\u0627\u0648\u06ce\u06a9\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648\u06cc \u0647\u06d5\u0628\u06ce\u062a\u060c \u0648 \u0626\u06ce\u0645\u06d5 \u0646\u0627\u06cc\u0634\u0627\u0631\u06cc\u0646\u06d5\u0648\u06d5. \u0626\u06d5\u06af\u06d5\u0631 \u06a9\u06d5\u0633\u06d5\u06a9\u06d5\u062a \u0646\u0627\u0633\u06cc\u06cc\u06d5\u0648\u06d5\u060c \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u0626\u06d5\u0631\u06a9\u06d5\u06a9\u06d5 \u0628\u06af\u06d5\u0695\u06ce\u0646\u06d5\u0648\u06d5."},
