galR(){return"\u0695\u0627\u06af\u0631\u062a\u0646 \u0648 \u0626\u0627\u06af\u0627\u062f\u0627\u0631\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gam1(){return"\u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u0631\u0627\u0648\u06d5"},
